63	    /**
64	     * Calculate the next partition for the topic based on the partition load stats.
65	     */
66	    private int nextPartition(Cluster cluster) {
67	        int random = randomPartition();
68	
69	        // Cache volatile variable in local variable.
70	        PartitionLoadStats partitionLoadStats = this.partitionLoadStats;
71	        int partition;
72	
73	        if (partitionLoadStats == null) {
74	            // We don't have stats to do adaptive partitioning (or it's disabled), just switch to the next
75	            // partition based on uniform distribution.
76	            List<PartitionInfo> availablePartitions = cluster.availablePartitionsForTopic(topic);
77	            if (!availablePartitions.isEmpty()) {
78	                partition = availablePartitions.get(random % availablePartitions.size()).partition();
79	            } else {
80	                // We don't have available partitions, just pick one among all partitions.
81	                List<PartitionInfo> partitions = cluster.partitionsForTopic(topic);
82	                partition = random % partitions.size();
83	            }
84	        } else {
85	            // Calculate next partition based on load distribution.
86	            // Note that partitions without leader are excluded from the partitionLoadStats.
87	            assert partitionLoadStats.length > 0;
88	
89	            int[] cumulativeFrequencyTable = partitionLoadStats.cumulativeFrequencyTable;
90	            int weightedRandom = random % cumulativeFrequencyTable[partitionLoadStats.length - 1];
91	
92	            // By construction, the cumulative frequency table is sorted, so we can use binary
93	            // search to find the desired index.
94	            int searchResult = Arrays.binarySearch(cumulativeFrequencyTable, 0, partitionLoadStats.length, weightedRandom);
95	
96	            // binarySearch results the index of the found element, or -(insertion_point) - 1
97	            // (where insertion_point is the index of the first element greater than the key).
98	            // We need to get the index of the first value that is strictly greater, which
99	            // would be the insertion point, except if we found the element that's equal to
100	            // the searched value (in this case we need to get next).  For example, if we have
101	            //  4 5 8
102	            // and we're looking for 3, then we'd get the insertion_point = 0, and the function
103	            // would return -0 - 1 = -1, by adding 1 we'd get 0.  If we're looking for 4, we'd
104	            // get 0, and we need the next one, so adding 1 works here as well.
105	            int partitionIndex = Math.abs(searchResult + 1);
106	            assert partitionIndex < partitionLoadStats.length;
107	            partition = partitionLoadStats.partitionIds[partitionIndex];
108	        }
109	
110	        log.trace("Switching to partition {} in topic {}", partition, topic);
111	        return partition;
112	    }
