                int[] reorderedQueueSizes = new int[length];
                int[] reorderedPartitionIds = new int[length];
                int localIdx = 0;
                int remoteIdx = localCount;
                for (int i = 0; i < length; i++) {
                    int dst = rack.equals(partitionRacks[i]) ? localIdx++ : remoteIdx++;
                    reorderedQueueSizes[dst] = queueSizes[i];
                    reorderedPartitionIds[dst] = partitionIds[i];
